-- Todas as contagens abaixo devem ser zero antes de adicionar FKs ao schema da API.
SELECT 'PET_TUTOR' AS REGRA, COUNT(*) AS ORFAOS FROM TBPET p WHERE NOT EXISTS (SELECT 1 FROM TBTUTOR t WHERE t.IDTUTOR=p.IDTUTOR)
UNION ALL SELECT 'PET_ESPECIE', COUNT(*) FROM TBPET p WHERE NOT EXISTS (SELECT 1 FROM TBESPECIE e WHERE e.IDESPECIE=p.IDESPECIE)
UNION ALL SELECT 'PET_RACA', COUNT(*) FROM TBPET p WHERE p.IDRACA IS NOT NULL AND NOT EXISTS (SELECT 1 FROM TBRACA r WHERE r.IDRACA=p.IDRACA AND r.IDESPECIE=p.IDESPECIE)
UNION ALL SELECT 'PET_CLINICA', COUNT(*) FROM TBPET p WHERE p.IDCLINICA IS NOT NULL AND NOT EXISTS (SELECT 1 FROM TBCLINICA c WHERE c.IDCLINICA=p.IDCLINICA)
UNION ALL SELECT 'LEMBRETE_PET', COUNT(*) FROM TBLEMBRETE l WHERE NOT EXISTS (SELECT 1 FROM TBPET p WHERE p.IDPET=l.IDPET);
